// Package gen turns a schema snapshot into Go source code.
package gen

import (
	"bytes"
	"embed"
	"fmt"
	"go/format"
	"sort"
	"strconv"
	"strings"
	"text/template"

	"github.com/tobibamidele/lathe/schema"
)

//go:embed templates/*.tmpl
var templateFS embed.FS

// File is one generated source file.
type File struct {
	Name    string
	Content []byte
}

// Header starts every generated file; the CLI uses it to recognise files it
// may delete when a table disappears.
const Header = "// Code generated by lathe. DO NOT EDIT."

// Generate renders the Go package for exp.
func Generate(exp *schema.Export) ([]File, error) {
	tables, err := buildViews(exp)
	if err != nil {
		return nil, err
	}
	funcs := template.FuncMap{"quote": strconv.Quote}
	tmpl, err := template.New("").Funcs(funcs).ParseFS(templateFS, "templates/*.tmpl")
	if err != nil {
		return nil, err
	}

	var files []File
	render := func(name, tmplName string, data any) error {
		var buf bytes.Buffer
		if err := tmpl.ExecuteTemplate(&buf, tmplName, data); err != nil {
			return fmt.Errorf("gen: rendering %s: %w", name, err)
		}
		src, err := format.Source(buf.Bytes())
		if err != nil {
			return fmt.Errorf("gen: formatting %s: %w\n%s", name, err, buf.String())
		}
		files = append(files, File{Name: name, Content: src})
		return nil
	}

	for _, t := range tables {
		t.Package = exp.Config.Package
		if err := render(t.Name+".gen.go", "table.go.tmpl", t); err != nil {
			return nil, err
		}
	}
	if len(tables) > 0 {
		err = render("client.gen.go", "client.go.tmpl", struct {
			Package string
			First   string
			Tables  []*tableView
		}{exp.Config.Package, tables[0].Vars, tables})
		if err != nil {
			return nil, err
		}
	}
	return files, nil
}

// ---- view models ----

type enumValue struct {
	Const string
	Value string
	enum  *enumView
}

type enumView struct {
	Type   string
	Field  string
	Values []enumValue
}

type fieldView struct {
	Column        string
	Name          string
	Param         string // lower camel case, for Get parameters
	GoType        string
	BaseType      string
	PrimaryKey    bool
	AutoIncrement bool
	OmitZero      bool
}

type tableView struct {
	Package    string
	Name       string
	Model      string
	Vars       string
	Spec       string
	Fields     []fieldView
	PrimaryKey []fieldView
	Enums      []*enumView
	Imports    []string
}

// EnumType returns the Go type of an enum constant; it exists so the template
// can refer to the enclosing enum from inside a nested range.
func (t *tableView) EnumType(v enumValue) string { return v.enum.Type }

// Names that would collide with generated identifiers.
var reservedModels = map[string]bool{"Client": true, "NewClient": true}
var reservedVars = map[string]bool{
	"DB": true, "Tx": true, "TxOptions": true, "Exec": true, "Query": true, "Close": true,
	"Ping": true, "Dialect": true, "SQL": true, "InTx": true,
}

func buildViews(exp *schema.Export) ([]*tableView, error) {
	var views []*tableView
	seen := map[string]string{} // package level identifier -> table
	claim := func(ident, table string) error {
		if other, dup := seen[ident]; dup {
			return fmt.Errorf("gen: tables %q and %q both generate the identifier %s; give one of them a different .Model(...)", other, table, ident)
		}
		seen[ident] = table
		return nil
	}

	for _, t := range exp.Snapshot.Tables {
		model := t.Model
		if model == "" {
			model = pascal(singular(t.Name))
		}
		vars := pascal(t.Name)
		if vars == model {
			vars += "Table"
		}
		if reservedModels[model] {
			return nil, fmt.Errorf("gen: table %q would generate a type named %s, which lathe reserves; give it .Model(\"...\")", t.Name, model)
		}
		if reservedVars[vars] {
			return nil, fmt.Errorf("gen: table %q would generate a Client field named %s, which collides with a Client method; rename the table", t.Name, vars)
		}
		for _, id := range []string{model, model + "Columns", model + "Client", vars} {
			if err := claim(id, t.Name); err != nil {
				return nil, err
			}
		}

		v := &tableView{Name: t.Name, Model: model, Vars: vars, Spec: lowerFirst(model) + "Spec"}
		imports := map[string]bool{
			`"context"`:                       true,
			`"github.com/tobibamidele/lathe"`: true,
		}
		fieldNames := map[string]string{}
		for _, c := range t.Columns {
			name := c.Field
			if name == "" {
				name = pascal(c.Name)
			}
			if other, dup := fieldNames[name]; dup {
				return nil, fmt.Errorf("gen: table %q: columns %q and %q both become the field %s; set .Field(\"...\") on one", t.Name, other, c.Name, name)
			}
			fieldNames[name] = c.Name

			base, imp := goType(c, model, name)
			if imp != "" {
				imports[imp] = true
			}
			goT := base
			if c.Nullable && !strings.HasPrefix(base, "[]") && base != "lathe.JSON" {
				goT = "*" + base
			}
			f := fieldView{
				Column: c.Name, Name: name, Param: paramName(name),
				GoType: goT, BaseType: base,
				PrimaryKey: t.IsPrimaryKey(c.Name), AutoIncrement: c.AutoIncrement,
				OmitZero: omitZero(c),
			}
			v.Fields = append(v.Fields, f)
			if f.PrimaryKey {
				v.PrimaryKey = append(v.PrimaryKey, f)
			}
			if c.Type.Kind == schema.KindEnum {
				e := &enumView{Type: model + name, Field: name}
				consts := map[string]string{}
				for _, val := range c.Type.Values {
					cn := e.Type + pascal(val)
					if other, dup := consts[cn]; dup {
						return nil, fmt.Errorf("gen: table %q column %q: enum values %q and %q both become %s", t.Name, c.Name, other, val, cn)
					}
					consts[cn] = val
					e.Values = append(e.Values, enumValue{Const: cn, Value: val, enum: e})
				}
				if err := claim(e.Type, t.Name); err != nil {
					return nil, err
				}
				for _, ev := range e.Values {
					if err := claim(ev.Const, t.Name); err != nil {
						return nil, err
					}
				}
				v.Enums = append(v.Enums, e)
			}
		}
		// keep primary key parameters in declared key order
		sort.SliceStable(v.PrimaryKey, func(i, j int) bool {
			return indexOf(t.PrimaryKey, v.PrimaryKey[i].Column) < indexOf(t.PrimaryKey, v.PrimaryKey[j].Column)
		})
		for imp := range imports {
			v.Imports = append(v.Imports, imp)
		}
		sort.Strings(v.Imports)
		views = append(views, v)
	}
	return views, nil
}

func indexOf(list []string, s string) int {
	for i, x := range list {
		if x == s {
			return i
		}
	}
	return -1
}

// goType returns the Go type of a column and the import it needs, if any.
func goType(c *schema.ColumnDef, model, field string) (string, string) {
	switch c.Type.Kind {
	case schema.KindSmallInt:
		return "int16", ""
	case schema.KindInt:
		return "int32", ""
	case schema.KindBigInt:
		return "int64", ""
	case schema.KindReal:
		return "float32", ""
	case schema.KindDouble:
		return "float64", ""
	case schema.KindDecimal:
		return "decimal.Decimal", `"github.com/shopspring/decimal"`
	case schema.KindBool:
		return "bool", ""
	case schema.KindVarChar, schema.KindText:
		return "string", ""
	case schema.KindUUID:
		return "uuid.UUID", `"github.com/google/uuid"`
	case schema.KindTimestamp, schema.KindDate:
		return "time.Time", `"time"`
	case schema.KindJSON:
		return "lathe.JSON", ""
	case schema.KindBytes:
		return "[]byte", ""
	case schema.KindEnum:
		return model + field, ""
	}
	panic("gen: unknown kind " + string(c.Type.Kind))
}

// omitZero reports whether a zero Go value in this column means "not set", so
// INSERT should leave the column out and let the database default apply.
//
// A zero bool, number or string is a legitimate value, so constant defaults on
// those columns are never applied behind the caller's back; declare the column
// Nullable to get the default when the pointer is nil.
func omitZero(c *schema.ColumnDef) bool {
	d := c.Default
	switch {
	case d == nil:
		return false
	case c.Nullable:
		return true
	case d.Kind != schema.DefaultLiteral:
		return true
	}
	return c.Type.Kind == schema.KindEnum
}

func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}

var goKeywords = map[string]bool{
	"break": true, "case": true, "chan": true, "const": true, "continue": true, "default": true,
	"defer": true, "else": true, "fallthrough": true, "for": true, "func": true, "go": true,
	"goto": true, "if": true, "import": true, "interface": true, "map": true, "package": true,
	"range": true, "return": true, "select": true, "struct": true, "switch": true, "type": true,
	"var": true, "ctx": true,
}

// paramName turns a field name into a parameter name: UserID -> userID.
func paramName(field string) string {
	// lower the leading run of capitals, keeping a trailing initialism word intact
	r := []rune(field)
	n := 0
	for n < len(r) && r[n] >= 'A' && r[n] <= 'Z' {
		n++
	}
	switch {
	case n == 0:
	case n == len(r) || n == 1:
		r = []rune(strings.ToLower(string(r[:n])) + string(r[n:]))
	default:
		r = []rune(strings.ToLower(string(r[:n-1])) + string(r[n-1:]))
	}
	p := string(r)
	if goKeywords[p] {
		p += "Value"
	}
	return p
}
